package net.minecraft.world; import net.minecraft.tileentity.TileEntity; import net.minecraft.util.math.BlockPos; import java.util.*; public class World { public boolean isRemote; public final Map<BlockPos,TileEntity> tiles=new HashMap<BlockPos,TileEntity>(); public final Set<BlockPos> unloaded=new HashSet<BlockPos>(); public BlockPos failQuery; public boolean isBlockLoaded(BlockPos p){if(p.equals(failQuery)) throw new RuntimeException("world query");return !unloaded.contains(p);} public TileEntity getTileEntity(BlockPos p){return tiles.get(p);} }
